const m = $input.first().json;
let texto = m.text || m.textPlain || m.snippet || '';

// cortar en el primer marcador de historial citado
const cortes = [
  /^El .* escribió:/m, /^On .* wrote:/m,
  /^-{2,}\s*Mensaje original\s*-{2,}/mi, /^De:\s/m, /^From:\s/m,
];
for (const re of cortes) {
  const hit = texto.match(re);
  if (hit) texto = texto.slice(0, hit.index);
}

// quitar lineas citadas y firma
texto = texto
  .split('\n').filter(l => !l.trim().startsWith('>')).join('\n')
  .split(/^--\s*$/m)[0]
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, 3000);

// el asunto puede venir en la raiz o en los encabezados del mensaje
const encabezados = m.payload?.headers || m.headers || [];
const buscarHeader = (nombre) =>
  (Array.isArray(encabezados)
    ? encabezados.find(h => String(h.name).toLowerCase() === nombre)?.value
    : encabezados?.[nombre]) || '';

const asunto = m.subject || m.Subject || buscarHeader('subject') || '(sin asunto)';

// el remitente puede llegar como objeto o como texto crudo
const crudo = String(m.from?.value?.[0]?.address || m.From || m.from || buscarHeader('from') || '');
const soloCorreo = (crudo.match(/[^\s<>,;"]+@[^\s<>,;"]+/) || [''])[0].toLowerCase().trim();
const nombre = m.from?.value?.[0]?.name
  || crudo.split('<')[0].replace(/"/g, '').trim()
  || soloCorreo.split('@')[0];

// identificador legible del ticket
const ahora = new Date();
const p = (n) => String(n).padStart(2, '0');
const ticketId = `TK-${ahora.getFullYear()}${p(ahora.getMonth() + 1)}${p(ahora.getDate())}` +
                 `-${p(ahora.getHours())}${p(ahora.getMinutes())}${p(ahora.getSeconds())}`;

return [{ json: {
  ticket_id: ticketId,
  correo: soloCorreo,
  nombre: nombre,
  asunto: asunto,
  descripcion_limpia: texto,
  threadId: m.threadId,
  messageId: m.id,
  recibido: ahora.toISOString(),
}}];

const t = $('Limpiar y preparar').first().json;
const sol = $('Buscar solicitante').first().json;
const sf = sol.fields || sol;

const activos = $('Leer activos').all()
  .map(i => { const f = i.json.fields || i.json; return f['Código'] ? `${f['Código']} | ${f.Nombre} | ${f['Palabras clave'] || ''}` : null; })
  .filter(Boolean)
  .join('\n');

const categorias = [
  'Acceso y contrasenas', 'Software y ERP', 'Hardware y equipos', 'Red e internet',
  'Mantenimiento mecanico', 'Mantenimiento electrico', 'Instrumentacion y control',
  'Infraestructura y servicios',
];

const prompt = `Clasifica esta solicitud de la mesa de ayuda de una planta manufacturera.

ASUNTO: ${t.asunto}

DESCRIPCION:
${t.descripcion_limpia}

AREA DEL SOLICITANTE: ${sf['Área'] || 'no registrada'}

CATEGORIAS PERMITIDAS (usa exactamente una de estas):
${categorias.join('\n')}

ACTIVOS REGISTRADOS (codigo | nombre | como lo llaman):
${activos || 'sin catalogo disponible'}

Devuelve EXACTAMENTE este JSON, sin texto adicional ni bloques de codigo:
{"categoria":"una de las permitidas","criticidad_propuesta":"baja|media|alta|critica","resumen":"una linea de maximo 90 caracteres","activo_detectado":"codigo del activo o null","parada_de_linea":true|false,"informacion_suficiente":true|false,"datos_faltantes":["..."],"confianza":"alta|media|baja"}

Reglas:
- parada_de_linea true solo si el texto dice o implica que la produccion esta detenida.
- informacion_suficiente false si no se puede saber que equipo o sistema falla, o que esta pasando.
- No infieras urgencia por mayusculas o signos de admiracion: evalua el impacto descrito.
- Si no encaja en ninguna categoria, confianza baja.`;

return [{ json: { __prompt: prompt, area: sf['Área'] || 'No registrada',
                  solicitante_id: sol.id || null } }];
const encabezados = '(sin asunto)';

const resp = $input.first().json;
const t = $('Limpiar y preparar').first().json;
const prep = $('Preparar prompt').first().json;

const CATEGORIAS = ['Acceso y contrasenas', 'Software y ERP', 'Hardware y equipos',
  'Red e internet', 'Mantenimiento mecanico', 'Mantenimiento electrico',
  'Instrumentacion y control', 'Infraestructura y servicios'];

const ESPECIALIDAD = {
  'Acceso y contrasenas': 'TI', 'Software y ERP': 'TI',
  'Hardware y equipos': 'TI', 'Red e internet': 'TI',
  'Mantenimiento mecanico': 'Mecanico', 'Mantenimiento electrico': 'Electrico',
  'Instrumentacion y control': 'Instrumentacion', 'Infraestructura y servicios': 'Infraestructura',
};

const NIVEL = { baja: 1, media: 2, alta: 3, critica: 4 };
const NOMBRE = { 1: 'Baja', 2: 'Media', 3: 'Alta', 4: 'Critica' };
const SLA = { 1: 24, 2: 8, 3: 4, 4: 2 };

const base = {
  'ID ticket': t.ticket_id,
  'Fecha recepcion': t.recibido,
  'Correo solicitante': t.correo,
  Asunto: t.asunto,
  'Descripcion limpia': t.descripcion_limpia,
  threadId: t.threadId,
  messageId: t.messageId,
  solicitante_link: prep.solicitante_id ? [prep.solicitante_id] : null,
};

let ia;
try {
  const bruto = resp.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  ia = JSON.parse(bruto.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {
  return [{ json: { ...base, ruta: 'manual', 'Estado': 'Gestion manual',
                    'Confianza IA': 'Baja', 'Criticidad final': 'Media', 'SLA horas': 8,
                    motivo_manual: 'El modelo no devolvio JSON valido' } }];
}

// categoría validada contra el catálogo cerrado
const categoria = CATEGORIAS.includes(ia.categoria) ? ia.categoria : null;
if (!categoria || ia.confianza === 'baja') {
  return [{ json: { ...base, ruta: 'manual', 'Estado': 'Gestion manual',
                    'Categoria': categoria || 'Sin clasificar',
                    'Resumen IA': ia.resumen || '',
                    'Confianza IA': 'Baja', 'Criticidad final': 'Media', 'SLA horas': 8,
                    motivo_manual: categoria ? 'Confianza baja del modelo'
                                             : 'Categoria fuera del catalogo' } }];
}

// criticidad: la IA propone, las reglas deciden
let nivel = NIVEL[String(ia.criticidad_propuesta || '').toLowerCase()] || 2;
const nivelIA = nivel;

const activos = $('Leer activos').all().map(i => ({ id: i.json.id, ...(i.json.fields || i.json) }));
const activo = ia.activo_detectado
  ? activos.find(a => a['Código'] === ia.activo_detectado)
  : null;

if (activo && activo['Critico para produccion']) nivel = Math.max(nivel, 3);
if (ia.parada_de_linea === true) nivel = 4;

// técnico: el responsable del activo, o el de la especialidad de la categoría
const tecnicos = $('Leer tecnicos').all().map(i => ({ id: i.json.id, ...(i.json.fields || i.json) }));
let tecnico = null;
if (activo && Array.isArray(activo['Tecnico responsable']) && activo['Tecnico responsable'].length) {
  tecnico = tecnicos.find(x => x.id === activo['Tecnico responsable'][0]) || null;
}
if (!tecnico) {
  tecnico = tecnicos.find(x => x.Especialidad === ESPECIALIDAD[categoria] && x.Activo !== false) || null;
}

const suficiente = ia.informacion_suficiente !== false;
const ruta = !suficiente ? 'info' : (nivel >= 3 ? 'alta' : 'normal');

return [{ json: {
  ...base,
  Categoria: categoria,
  'Criticidad IA': NOMBRE[nivelIA],
  'Criticidad final': NOMBRE[nivel],
  'SLA horas': SLA[nivel],
  'Resumen IA': ia.resumen || '',
  'Confianza IA': ia.confianza === 'media' ? 'Media' : 'Alta',
  'Informacion suficiente': suficiente,
  Estado: ruta === 'info' ? 'Requiere info' : 'Recibido',
  activo_link: activo ? [activo.id] : null,
  activo_codigo: activo ? activo['Código'] : null,
  activo_nombre: activo ? activo.Nombre : 'no identificado',
  tecnico_link: tecnico ? [tecnico.id] : null,
  tecnico_nombre: tecnico ? tecnico.Nombre : 'sin asignar',
  tecnico_chat_id: tecnico ? tecnico['Chat ID Telegram'] : null,
  datos_faltantes: Array.isArray(ia.datos_faltantes) ? ia.datos_faltantes : [],
  nivel,
  ruta,
}}];

const d = $('Reglas y criticidad').first().json;
const t = $('Limpiar y preparar').first().json;

const prompt = `Redacta la respuesta al solicitante de un ticket de soporte interno.

TICKET: ${d['ID ticket']}
CATEGORIA: ${d.Categoria}
CRITICIDAD: ${d['Criticidad final']} (tiempo de atencion comprometido: ${d['SLA horas']} horas)
EQUIPO O SISTEMA: ${d.activo_nombre}
TECNICO ASIGNADO: ${d.tecnico_nombre}

LO QUE REPORTO EL SOLICITANTE:
${t.descripcion_limpia}

Escribe un correo breve en espanol, maximo 120 palabras, tono sereno y profesional.
Debe: acusar recibo citando el numero de ticket, confirmar que se entendio el problema en una frase,
indicar el tiempo de atencion comprometido y el tecnico asignado, y listar de una a tres acciones
inmediatas y seguras que el solicitante puede verificar mientras llega el tecnico.
No prometas tiempos de solucion. No inventes causas ni datos que no esten arriba.
No incluyas asunto ni firma: solo el cuerpo en HTML simple.`;

return [{ json: { ...d, __prompt: prompt } }];

const tickets = $input.all().map(i => ({ id: i.json.id, ...(i.json.fields || i.json) }));

// fecha local de Bogotá: toISOString() devuelve UTC y corre el día después de las 7 pm
const enBogota = (f) =>
  new Date(f).toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });

const hoy = enBogota(new Date());
const deHoy = tickets.filter(t => t['Fecha recepcion'] && enBogota(t['Fecha recepcion']) === hoy);

const horas = (desde) => (Date.now() - new Date(desde).getTime()) / 36e5;

// vencidos: abiertos cuyo tiempo transcurrido supera su SLA (número contra número)
const vencidos = tickets.filter(t =>
  !['Cerrado', 'Atendido'].includes(t.Estado) &&
  t['Fecha recepcion'] &&
  horas(t['Fecha recepcion']) > Number(t['SLA horas'] || 24));

const cumplen = deHoy.filter(t => t['Cumple SLA'] === 'Sí').length;
const incumplen = deHoy.filter(t => t['Cumple SLA'] === 'No').length;

const aprobados = deHoy.filter(t => t['Decision humana'] === 'Aprobado').length;
const rechazados = deHoy.filter(t => t['Decision humana'] === 'Rechazado').length;

// volumen de salida: correos que realmente llegaron al solicitante
const volumenSalida = deHoy.filter(t => t['Fecha primera respuesta']).length;

const errores = deHoy.filter(t => t.Estado === 'Error').length;

const kpis = {
  Fecha: hoy,
  Recibidos: deHoy.length,
  Clasificados: deHoy.filter(t => t.Categoria && t.Categoria !== 'Sin clasificar').length,
  'Requieren info': deHoy.filter(t => t.Estado === 'Requiere info').length,
  'Criticidad alta': deHoy.filter(t => ['Alta', 'Critica'].includes(t['Criticidad final'])).length,
  Aprobados: aprobados,
  Rechazados: rechazados,
  'Volumen de salida': volumenSalida,
  'Cumplen SLA': cumplen,
  'Incumplen SLA': incumplen,
  Errores: errores,
};

// las tres tasas que pide la rúbrica, para el mensaje de Telegram
const pct = (n, d) => (d === 0 ? 'sin datos' : Math.round((n / d) * 100) + '%');
const tasaAprobacion = pct(aprobados, aprobados + rechazados);
const tasaError = pct(errores, deHoy.length);
const tasaSLA = pct(cumplen, cumplen + incumplen);

const linea = (t) =>
  `- ${t['ID ticket'] || t.Asunto} (${t['Criticidad final'] || 'sin criticidad'}) ${t['Resumen IA'] || ''}`;
const bloque = (titulo, items) => items.length
  ? `\n\n*${titulo}* (${items.length})\n` + items.slice(0, 10).map(linea).join('\n')
  : '';

kpis.mensaje =
  `*Mesa de ayuda - ${hoy}*\n` +
  `Recibidos: ${deHoy.length} | Volumen de salida: ${volumenSalida}\n` +
  `Tasa de aprobacion: ${tasaAprobacion} | Tasa de error: ${tasaError} | Cumplimiento SLA: ${tasaSLA}` +
  bloque('Fuera de SLA, requieren gestion', vencidos) +
  bloque('Esperan tu aprobacion', tickets.filter(t => t.Estado === 'Pendiente aprobacion')) +
  bloque('Esperan datos del solicitante', tickets.filter(t => t.Estado === 'Requiere info')) +
  bloque('Sin clasificar por fallo tecnico', tickets.filter(t => t.Estado === 'Error'));

return [{ json: kpis }];
